package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)

	// Read first line: n rows, m columns
	scanner.Scan()
	firstLine := strings.Fields(scanner.Text())
	n, _ := strconv.Atoi(firstLine[0])
	m, _ := strconv.Atoi(firstLine[1])

	// Create grid with padding (n+2 x m+2)
	grid := make([][]byte, n+2)
	for i := range grid {
		grid[i] = make([]byte, m+2)
		for j := range grid[i] {
			grid[i][j] = '.'
		}
	}

	// Read grid lines
	for i := 1; i <= n; i++ {
		scanner.Scan()
		line := scanner.Text()
		for j := 1; j <= m; j++ {
			grid[i][j] = line[j-1]
		}
	}

	output := 0
	// Directions: Up, Down, Left, Right
	dirs := [][2]int{{-1, 0}, {1, 0}, {0, -1}, {0, 1}}

	for i := 1; i <= n; i++ {
		for j := 1; j <= m; j++ {
			if grid[i][j] == 'W' {
				for _, d := range dirs {
					ni, nj := i+d[0], j+d[1]
					if grid[ni][nj] == 'P' {
						output++
						break // Each wolf eats at most one pig
					}
				}
			}
		}
	}

	fmt.Println(output)
}

